import { test } from 'node:test';
import assert from 'node:assert/strict';
import { JOBS } from '../src/jobs/index.js';

// #9, #12: the 500 body is shown on the scheduler's admin screen (see CONTRIBUTING.md, "失敗の応答").
// Every job in JOBS must answer a database error with the fixed message, whatever the job is.
const SECRET = 'db down at 10.0.0.5';
const brokenDb = new Proxy({}, { get: () => () => { throw new Error(SECRET); } });

for (const [name, job] of Object.entries(JOBS)) {
  test(`${name}: the 500 body carries the fixed message, not the internal error text`, () => {
    const res = job.run({ db: brokenDb, email: 'a@example.com' });
    assert.equal(res.status, 500);
    assert.equal(res.body.error, 'internal error');
    assert.doesNotMatch(JSON.stringify(res.body), /db down|10\.0\.0\.5/);
  });
}

