node --input-type=module -e '
import assert from "node:assert/strict";
import { execSync } from "node:child_process";
const SECRET = "db down at 10.0.0.5";
const brokenDb = new Proxy({}, { get: () => () => { throw new Error(SECRET); } });
const check = (job) => {
  const res = job.run({ db: brokenDb, email: "a@example.com" });
  assert.equal(res.status, 500);
  assert.equal(res.body.error, "internal error");
  assert.doesNotMatch(JSON.stringify(res.body), /db down|10\.0\.0\.5/);
};
const verdict = (name, job) => { try { check(job); console.log("PASSES (undetected):", name); } catch (e) { console.log("fails (detected):  ", name, "--", String(e.message).split("\n")[0]); } };
// pre-fix versions of each job from master, loaded in memory
for (const n of ["cleanup","digest","reindex","rollup","subscribe"]) {
  const src = execSync(`git show master:src/jobs/${n}.js`).toString();
  const mod = await import("data:text/javascript," + encodeURIComponent(src));
  verdict("master:" + n, mod);
}
const one = (body) => ({ run({ db }) { try { db.x(); return { status: 200, body: {} }; } catch (err) { return { status: 500, body: body(err) }; } } });
verdict("err.message in error", one(e => ({ ok:false, error: e.message })));
verdict("template string in error", one(e => ({ ok:false, error: `failed: ${e}` })));
verdict("fixed error + detail: err.stack", one(e => ({ ok:false, error: "internal error", detail: e.stack })));
verdict("fixed error + err object (JSON -> {})", one(e => ({ ok:false, error: "internal error", cause: e })));
verdict("fixed error + err.name", one(e => ({ ok:false, error: "internal error", kind: e.name })));
verdict("async job leaking", { async run({ db }) { try { await db.x(); } catch (err) { return { status: 500, body: { error: String(err) } }; } } });
verdict("job never touching db", { run() { return { status: 200, body: { ok: true } }; } });
verdict("no try/catch", { run({ db }) { db.x(); } });
verdict("two-stage: 1st catch fixed, 2nd catch leaks", { run({ db }) { let rows; try { rows = db.a(); } catch (err) { return { status: 500, body: { ok:false, error: "internal error" } }; } try { db.b(rows); return { status: 200, body: {} }; } catch (err) { return { status: 500, body: { ok:false, error: String(err) } }; } } });
